806|YAML_DECLARE(int)
807|yaml_parser_fetch_more_tokens(yaml_parser_t *parser)
808|{
809|    int need_more_tokens;
810|
811|    /* While we need more tokens to fetch, do it. */
812|
813|    while (1)
814|    {
815|        /*
816|         * Check if we really need to fetch more tokens.
817|         */
818|
819|        need_more_tokens = 0;
820|
821|        if (parser->tokens.head == parser->tokens.tail)
822|        {
823|            /* Queue is empty. */
824|
825|            need_more_tokens = 1;
826|        }
827|        else
828|        {
829|            yaml_simple_key_t *simple_key;
830|
831|            /* Check if any potential simple key may occupy the head position. */
832|
833|            if (!yaml_parser_stale_simple_keys(parser))
834|                return 0;
835|
836|            for (simple_key = parser->simple_keys.start;
837|                    simple_key != parser->simple_keys.top; simple_key++) {
838|                if (simple_key->possible
839|                        && simple_key->token_number == parser->tokens_parsed) {
840|                    need_more_tokens = 1;
841|                    break;
842|                }
843|            }
844|        }
845|
846|        /* We are finished. */
847|
848|        if (!need_more_tokens)
849|            break;
850|
851|        /* Fetch the next token. */
852|
853|        if (!yaml_parser_fetch_next_token(parser))
854|            return 0;
855|    }
856|
857|    parser->token_available = 1;
858|
859|    return 1;
860|}

