1461|yaml_parser_fetch_flow_collection_start(yaml_parser_t *parser,
1462|        yaml_token_type_t type)
1463|{
1464|    yaml_mark_t start_mark, end_mark;
1465|    yaml_token_t token;
1466|
1467|    /* The indicators '[' and '{' may start a simple key. */
1468|
1469|    if (!yaml_parser_save_simple_key(parser))
1470|        return 0;
1471|
1472|    /* Increase the flow level. */
1473|
1474|    if (!yaml_parser_increase_flow_level(parser))
1475|        return 0;
1476|
1477|    /* A simple key may follow the indicators '[' and '{'. */
1478|
1479|    parser->simple_key_allowed = 1;
1480|
1481|    /* Consume the token. */
1482|
1483|    start_mark = parser->mark;
1484|    SKIP(parser);
1485|    end_mark = parser->mark;
1486|
1487|    /* Create the FLOW-SEQUENCE-START of FLOW-MAPPING-START token. */
1488|
1489|    TOKEN_INIT(token, type, start_mark, end_mark);
1490|
1491|    /* Append the token to the queue. */
1492|
1493|    if (!ENQUEUE(parser, parser->tokens, token))
1494|        return 0;
1495|
1496|    return 1;
