315|
316|        case YAML_PARSE_FLOW_MAPPING_EMPTY_VALUE_STATE:
317|            return yaml_parser_parse_flow_mapping_value(parser, event, 1);
318|
319|        default:
320|            assert(1);      /* Invalid state. */
321|    }
