481|/*
482| * Parse the productions:
483| * implicit_document    ::= block_node DOCUMENT-END*
484| *                                     *************
485| * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
486| *                                                                *************
487| */
488|
489|static int
490|yaml_parser_parse_document_end(yaml_parser_t *parser, yaml_event_t *event)
491|{
492|    yaml_token_t *token;
493|    yaml_mark_t start_mark, end_mark;
494|    int implicit = 1;
495|
496|    token = PEEK_TOKEN(parser);
497|    if (!token) return 0;
498|
499|    start_mark = end_mark = token->start_mark;
500|
501|    if (token->type == YAML_DOCUMENT_END_TOKEN) {
502|        end_mark = token->end_mark;
503|        SKIP_TOKEN(parser);
504|        implicit = 0;
505|    }
506|
507|    while (!STACK_EMPTY(parser, parser->tag_directives)) {
508|        yaml_tag_directive_t tag_directive = POP(parser, parser->tag_directives);
509|        yaml_free(tag_directive.handle);
510|        yaml_free(tag_directive.prefix);
511|    }
512|
513|    parser->state = YAML_PARSE_DOCUMENT_START_STATE;
514|    DOCUMENT_END_EVENT_INIT(*event, implicit, start_mark, end_mark);
515|
516|    return 1;
517|}
