519|/*
520| * Parse the productions:
521| * block_node_or_indentless_sequence    ::=
522| *                          ALIAS
523| *                          *****
524| *                          | properties (block_content | indentless_block_sequence)?
525| *                            **********  *
526| *                          | block_content | indentless_block_sequence
527| *                            *
528| * block_node           ::= ALIAS
529| *                          *****
530| *                          | properties block_content?
531| *                            ********** *
532| *                          | block_content
533| *                            *
534| * flow_node            ::= ALIAS
535| *                          *****
536| *                          | properties flow_content?
537| *                            ********** *
538| *                          | flow_content
539| *                            *
540| * properties           ::= TAG ANCHOR? | ANCHOR TAG?
541| *                          *************************
542| * block_content        ::= block_collection | flow_collection | SCALAR
543| *                                                               ******
544| * flow_content         ::= flow_collection | SCALAR
545| *                                            ******
546| */
547|
548|static int
549|yaml_parser_parse_node(yaml_parser_t *parser, yaml_event_t *event,
550|        int block, int indentless_sequence)
551|{
552|    yaml_token_t *token;
553|    yaml_char_t *anchor = NULL;
554|    yaml_char_t *tag_handle = NULL;
555|    yaml_char_t *tag_suffix = NULL;
556|    yaml_char_t *tag = NULL;
557|    yaml_mark_t start_mark, end_mark, tag_mark;
558|    int implicit;
559|
560|    token = PEEK_TOKEN(parser);
