1209|
1210|static int
1211|yaml_parser_parse_flow_mapping_value(yaml_parser_t *parser,
1212|        yaml_event_t *event, int empty)
1213|{
1214|    yaml_token_t *token;
1215|
1216|    token = PEEK_TOKEN(parser);
1217|    if (!token) return 0;
1218|
1219|    if (empty) {
1220|        parser->state = YAML_PARSE_FLOW_MAPPING_KEY_STATE;
1221|        return yaml_parser_process_empty_scalar(parser, event,
1222|                token->start_mark);
1223|    }
1224|
1225|    if (token->type == YAML_VALUE_TOKEN) {
1226|        SKIP_TOKEN(parser);
1227|        token = PEEK_TOKEN(parser);
1228|        if (!token) return 0;
1229|        if (token->type != YAML_FLOW_ENTRY_TOKEN
1230|                && token->type != YAML_FLOW_MAPPING_END_TOKEN) {
1231|            if (!PUSH(parser, parser->states,
1232|                        YAML_PARSE_FLOW_MAPPING_KEY_STATE))
