80|            printf("+STR\n");
81|        else if (type == YAML_STREAM_END_EVENT)
82|            printf("-STR\n");
83|        else if (type == YAML_DOCUMENT_START_EVENT) {
84|            printf("+DOC");
85|            if (!event.data.document_start.implicit)
86|                printf(" ---");
87|            printf("\n");
88|        }
89|        else if (type == YAML_DOCUMENT_END_EVENT) {
90|            printf("-DOC");
91|            if (!event.data.document_end.implicit)
92|                printf(" ...");
93|            printf("\n");
94|        }
95|        else if (type == YAML_MAPPING_START_EVENT) {
96|            printf("+MAP");
97|            if (flow == 0 && event.data.mapping_start.style == YAML_FLOW_MAPPING_STYLE)
98|                printf(" {}");
99|            else if (flow == 1)
