117|            if (event.data.sequence_start.tag)
118|                printf(" <%s>", event.data.sequence_start.tag);
119|            printf("\n");
120|        }
121|        else if (type == YAML_SEQUENCE_END_EVENT)
122|            printf("-SEQ\n");
123|        else if (type == YAML_SCALAR_EVENT) {
124|            printf("=VAL");
125|            if (event.data.scalar.anchor)
126|                printf(" &%s", event.data.scalar.anchor);
127|            if (event.data.scalar.tag)
128|                printf(" <%s>", event.data.scalar.tag);
129|            switch (event.data.scalar.style) {
