59|        free(input);
60|    }
61|
62|    /* Test 2: nesting within the limit must succeed. */
63|    {
64|        int depth = 500;
65|        int len = depth * 2;
66|        input = (char *)malloc(len + 1);
67|        assert(input);
68|        for (i = 0; i < depth; i++)
69|            input[i] = '[';
70|        for (i = 0; i < depth; i++)
71|            input[depth + i] = ']';
72|        input[len] = '\0';
73|
74|        printf("Test 2: %d nested '[]' (within limit) ... ", depth);
75|        fflush(stdout);
76|        assert(scan_string(input, len) == 0);
77|        printf("OK (accepted)\n");
